def mask_components(mask):
    H,W=mask.shape; seen=set(); out=[]
    for r in range(H):
      for c in range(W):
       if mask[r,c] and (r,c) not in seen:
        st=[(r,c)]; seen.add((r,c)); cells=[]
        while st:
         y,x=st.pop();cells.append((y,x))
         for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
          yy,xx=y+dy,x+dx
          if 0<=yy<H and 0<=xx<W and mask[yy,xx] and (yy,xx) not in seen: seen.add((yy,xx));st.append((yy,xx))
        out.append(cells)
    return out

